signals.sql:
SELECT strftime(seen_at, '%Y-%m-%d') AS day,
       COUNT(*) AS flights
FROM flights GROUP BY 1 ORDER BY 2 DESC;

SELECT callsign, ac_type, reg, seen_at
FROM flights WHERE reg_country = 'CN'
ORDER BY first_seen DESC;

SELECT callsign, ac_type, reg, seen_at
FROM flights WHERE reg_country = 'US'
ORDER BY first_seen DESC;
